import{z as p,x as B,o as E,c as d,q as r,j as i,D as e,d as s,s as n,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"焦散矩阵 FEM","description":"","frontmatter":{"title":"焦散矩阵 FEM","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fem-matrix.md","filePath":"litho/fem-matrix.md","lastUpdated":1791413859000}'),A={name:"litho/fem-matrix.md"};function m(D,a,h,u,c,F){const t=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="焦散矩阵-fem" tabindex="-1">焦散矩阵 FEM <a class="header-anchor" href="#焦散矩阵-fem" aria-label="Permalink to &quot;焦散矩阵 FEM&quot;">​</a></h1><div class="epigraph"><p>工艺窗口不是画在纸上的椭圆。晶圆上按场变焦、变剂量，显影后量 CD，那张矩阵才是 E–D 图的实验源。</p><footer>—— 据 Mack 对 focus–exposure matrix 与 Bossung 测量的定义</footer></div><p><a href="/litho/ed-process-window">上一课</a>把合格区画成剂量–离焦平面上的重叠面积，并假定每个 \\((E,z)\\) 都有一个 CD 读数。缺口是：这个读数从哪次曝光来。本课把窗口铺成焦散矩阵（FEM, focus–exposure matrix）：场与场之间阶梯式改焦距和剂量，得到 Bossung 的数据骨架。空间均匀性（CDU）留给<a href="/litho/cdu-uniformity">下一课</a>，本课默认矩阵里的场代表「同一工艺点」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>E–D 窗是切过规格带之后的面积。没有矩阵，窗口只是模拟器里的等高线。产线缺口是一次可执行的曝光计划：哪些场走哪些 \\((E,z)\\)，步进多大，图形类别如何铺在同一片上，显影后量哪些垫。Mack 把 FEM 写成测量 Bossung 的标准动作，而不是又一种窗口定义。</p><p><span class="marginnote">Bossung 曲线就是「一族」CD–离焦曲线：每换一个剂量画一条，画完叠在一起。零离焦处曲线张得最开——剂量灵敏度最高；某条中间剂量的最平——最平意味着 CD 对离焦最不敏感。E–D 窗口的所有结论，都是从这族曲线切规格切出来的。</span></p><p>只扫焦或只扫剂量，得到的是窗的一条边。禁戒节距、孤立/密线若不同场才出现，重叠窗会假造。矩阵必须让关键图形在同一曝光条件下共存，否则交集没有实验对应物。</p><h3 id="矩阵消耗的是工艺预算-不是理论自由度" tabindex="-1">矩阵消耗的是工艺预算，不是理论自由度 <a class="header-anchor" href="#矩阵消耗的是工艺预算-不是理论自由度" aria-label="Permalink to &quot;矩阵消耗的是工艺预算，不是理论自由度&quot;">​</a></h3><p>每一场是一次不可复用的 \\((E,z)\\) 样本。场太多，晶圆与机时爆；场太少，Bossung 插值撒谎，isofocal 位置会漂。楔形调焦可以在一场内铺焦轴，剂量仍要按场或按扫描变。缺口是采样密度对窗口面积的误差，不是再推一次 \\(\\mathrm{DOF}\\propto\\lambda/\\mathrm{NA}^2\\)。</p><p><span class="marginnote">isofocal（等焦）点可以直觉理解为：一簇 Bossung 曲线「束腰」所在的剂量——设在这个剂量附近时，晶圆稍微离焦，CD 几乎不动。它就像天平的支点，左右都不倒。剂量选偏了，支点移位，同一台机器的可用焦深就莫名缩水。</span></p><p><span class="marginnote">FEM 上的「最佳焦」是矩阵里 CD 对焦最不敏感或落在规格中心的那一档，不一定等于扫描机当日的最佳调平。把 FEM 最佳焦直接写成产品曝光焦，会把矩阵的离散网格当成连续真值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型做法：晶圆按曝光场排列成网格，一轴步进剂量，一轴步进离焦（或用 focus drilling / 楔形在扫描方向铺焦）。显影后在每场的计量垫上量 CD，画 Bossung，切规格，得 EL 与 DOF，再与模拟对照。判据可加侧壁、残胶、桥连；EUV 孔层应另叠缺孔，不在平均 CD 矩阵里假装零缺陷。</p><p>模拟器校准后可以加密 \\((E,z)\\)，但验收以硅片 FEM 为准。换胶、换底层、换照明，矩阵要重打。RET 改了禁戒节距，旧 FEM 的重叠窗作废。</p><h3 id="与产品曝光的分工" tabindex="-1">与产品曝光的分工 <a class="header-anchor" href="#与产品曝光的分工" aria-label="Permalink to &quot;与产品曝光的分工&quot;">​</a></h3><p>FEM 是短环学习：故意把许多场打出规格，为的是看见边界。产品晶圆走窗口中心附近的窄带，不再铺满矩阵。把 FEM 的边缘场拿去报产能或套刻，是把实验设计当成产量。</p>',16)),(E(),i(l,null,{default:e(()=>[n(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E5%9C%BA%E7%BD%91%E6%A0%BC%3A%20%E5%89%82%E9%87%8F%20x%20%E7%A6%BB%E7%84%A6%22%5D%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%20FEM%22%5D%0A%20%20EXP%20--%3E%20CD%5B%22%E6%AF%8F%E5%9C%BA%E9%87%8F%20CD%22%5D%0A%20%20CD%20--%3E%20BOSS%5B%22Bossung%22%5D%0A%20%20BOSS%20--%3E%20ED%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20ED%20--%3E%20OV%5B%22%E5%A4%9A%E5%9B%BE%E5%BD%A2%E9%87%8D%E5%8F%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[s("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"剂量步进沿衬度曲线移动等剂量面；焦步进改变 NILS 与空中像调制。两者正交地改 CD，所以矩阵必须是二维的。扫描机的剂量是狭缝积分，离焦是调平与镜头场曲的叠加——FEM 的「设定焦」是工件台指令，不是晶圆每点真焦。场内已有焦指纹时，一场内的 CD 已经在扫一小段 Bossung；矩阵步进若小于该指纹，网格会和指纹缠在一起。",-1)),(E(),i(l,null,{default:e(()=>[n(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20ZM%5B%22%E7%A6%BB%E7%84%A6%20-0.15%20%E5%BE%AE%E7%B1%B3%E8%A1%8C%22%5D%0A%20%20%20%20A%5B%22%E4%BD%8E%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20B%5B%22%E4%B8%AD%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20C%5B%22%E9%AB%98%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%0A%20%20end%0A%20%20subgraph%20Z0%5B%22%E7%A6%BB%E7%84%A6%200%20%E8%A1%8C%22%5D%0A%20%20%20%20D%5B%22%E4%BD%8E%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20E%5B%22%E4%B8%AD%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20F%5B%22%E9%AB%98%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%0A%20%20end%0A%20%20subgraph%20ZP%5B%22%E7%A6%BB%E7%84%A6%20%2B0.15%20%E5%BE%AE%E7%B1%B3%E8%A1%8C%22%5D%0A%20%20%20%20G%5B%22%E4%BD%8E%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20H%5B%22%E4%B8%AD%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%20---%20I%5B%22%E9%AB%98%E5%89%82%E9%87%8F%E5%9C%BA%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>这张图回答的问题是：一张 FEM 落在晶圆上长什么样。每个曝光场是一格不可复用的 \\((E,z)\\) 样本，行扫焦、列扫剂量；格子越密，Bossung 插值越可信，但吃掉的晶圆与机时也越多。</p><p><span class="marginnote">数字实例：焦、剂量各取 5 档就是 \\(5 \\times 5 = 25\\) 个场的曝光加计量；缩成 \\(3 \\times 3\\) 只要 9 个场，省了六成机时，但两个采样点之间的窗口面积只能靠插值猜——缩小窗口的那一圈边界，恰恰最容易被漏采样。</span></p><p>浸没与 High-NA 焦轴预算薄，FEM 的焦步进要更密，否则窗口在采样之间被漏掉。剂量轴则受光源稳定与胶 \\(\\gamma\\) 限制：步进小于计量噪声就没有信息。</p><p><span class="marginnote">同一片 FEM 上 PEB 与显影必须尽量均匀。轨道把名义窗切碎时，矩阵读到的是破碎窗，不是光学 EL。先控轨道，再解释 Bossung 弯曲。</span></p><h3 id="计量链要锁在矩阵上" tabindex="-1">计量链要锁在矩阵上 <a class="header-anchor" href="#计量链要锁在矩阵上" aria-label="Permalink to &quot;计量链要锁在矩阵上&quot;">​</a></h3><p>上一课假设 CD 是真值。FEM 必须预先规定：SEM 还是散射测量、显影后还是刻蚀后、哪类图形、边缘算法。中途换计量，窗口面积会跳，看起来像工艺进步。</p><p><span class="marginnote">常见误区：初学者容易把「窗口变大」都当成工艺改进。实际上换一台 CD 计量设备、换一种线宽提取算法，都能让同一批数据读出更大的窗——量尺变了，不是窗变了。所以矩阵中途换计量，前后数据不能拼成一张图。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FEM 不含套刻，不含跨批次漂移，除非你故意把不同批次的矩阵画在一张图上——那是稳定性，不是单次窗口。模拟未校准 \\(\\ell\\)、\\(\\gamma\\) 时，加密网格只是光滑地错。禁戒节距要在照明固定后另扫节距，不能用一张剂量–焦矩阵代替。</p><p>后课默认：说到「打窗口」，就是打 FEM 并切重叠规格。CD 在晶圆上如何空间涨落，不是矩阵能回答的，下一课才是 CDU。</p><p><span class="marginnote">EL 百分比来自 FEM 在最佳焦处的剂量宽度。比较两张矩阵必须同一规格带、同一图形集、同一计量。面积竞赛否则无意义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FEM 是把 E–D 窗铺到晶圆场网格上的实验，Bossung 的数据源。</li><li>关键图形要共场，重叠窗才有实验对应。</li><li>设定焦是工件台指令；场内指纹会与步进缠绕。</li><li>产品走窗中心，FEM 走边界，不要混报。</li><li>空间 CDU 下一课。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',13))])}const g=p(A,[["render",m]]);export{f as __pageData,g as default};
